arguments.file_text:
@page "/apply"
@rendermode InteractiveServer
@using sv_0e97dbccf9a34995ad558771862bfbdc.Models
@using sv_0e97dbccf9a34995ad558771862bfbdc.Services
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="mb-4">Job Application</h2>

    @* ───── Step Indicator Bar ───── *@
    <nav class="d-flex justify-content-between mb-4 position-relative">
        @for (int i = 0; i < _stepLabels.Length; i++)
        {
            var step = i + 1;
            var isCompleted = step < _currentStep;
            var isCurrent = step == _currentStep;
            var isFuture = step > _currentStep;

            <button type="button"
                    class="btn btn-link text-decoration-none p-0 d-flex flex-column align-items-center flex-fill"
                    style="@(isFuture ? "opacity: 0.4; cursor: default;" : "cursor: pointer;")"
                    disabled="@(isFuture || _submitted)"
                    @onclick="() => GoToStep(step)">
                <span class="rounded-circle d-flex align-items-center justify-content-center mb-1"
                      style="width: 36px; height: 36px;
                             @(isCurrent ? "background-color: #0d6efd; color: white;" :
                               isCompleted ? "background-color: #198754; color: white;" :
                               "background-color: #dee2e6; color: #6c757d;")">
                    @if (isCompleted)
                    {
                        <span>&#10003;</span>
                    }
                    else
                    {
                        <span>@step</span>
                    }
                </span>
                <small class="@(isCurrent ? "fw-bold text-primary" : isCompleted ? "text-success" : "text-muted")">
                    @_stepLabels[i]
                </small>
            </button>
        }
    </nav>

    @if (_submitted)
    {
        @* ───── Confirmation ───── *@
        <div class="alert alert-success text-center py-5">
            <h3 class="mb-3">&#10003; Application Submitted!</h3>
            <p class="mb-0">Your application ID is <strong>@_applicationId</strong>.</p>
            <p class="text-muted mt-2">Thank you for applying. We will be in touch.</p>
        </div>
    }
    else
    {
        @* ───── Validation Errors ───── *@
        @if (_errors.Count > 0)
        {
            <div class="alert alert-danger">
                <ul class="mb-0">
