@page "/apply"
@rendermode InteractiveServer
@using sv_0e97dbccf9a34995ad558771862bfbdc.Models
@using sv_0e97dbccf9a34995ad558771862bfbdc.Services
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="mb-4">Job Application</h2>

    @* ───── Step Indicator Bar ───── *@
    <nav class="d-flex justify-content-between mb-4 position-relative">
        @for (int i = 0; i < _stepLabels.Length; i++)
        {
            var step = i + 1;
            var isCompleted = step < _currentStep;
            var isCurrent = step == _currentStep;
            var isFuture = step > _currentStep;

            <button type="button"
                    class="btn btn-link text-decoration-none p-0 d-flex flex-column align-items-center flex-fill"
                    style="@(isFuture ? "opacity: 0.4; cursor: default;" : "cursor: pointer;")"
                    disabled="@(isFuture || _submitted)"
                    @onclick="() => GoToStep(step)">
                <span class="rounded-circle d-flex align-items-center justify-content-center mb-1"
                      style="width: 36px; height: 36px;
                             @(isCurrent ? "background-color: #0d6efd; color: white;" :
                               isCompleted ? "background-color: #198754; color: white;" :
                               "background-color: #dee2e6; color: #6c757d;")">
                    @if (isCompleted)
                    {
                        <span>&#10003;</span>
                    }
                    else
                    {
                        <span>@step</span>
                    }
                </span>
                <small class="@(isCurrent ? "fw-bold text-primary" : isCompleted ? "text-success" : "text-muted")">
                    @_stepLabels[i]
                </small>
            </button>
        }
    </nav>

    @if (_submitted)
    {
        @* ───── Confirmation ───── *@
        <div class="alert alert-success text-center py-5">
            <h3 class="mb-3">&#10003; Application Submitted!</h3>
            <p class="mb-0">Your application ID is <strong>@_applicationId</strong>.</p>
            <p class="text-muted mt-2">Thank you for applying. We will be in touch.</p>
        </div>
    }
    else
    {
        @* ───── Validation Errors ───── *@
        @if (_errors.Count > 0)
        {
            <div class="alert alert-danger">
                <ul class="mb-0">
                    @foreach (var error in _errors)
                    {
                        <li>@error</li>
                    }
                </ul>
            </div>
        }

        @* ───── Step 1: Personal Info ───── *@
        @if (_currentStep == 1)
        {
            <h4>Personal Information</h4>
            <div class="mb-3">
                <label class="form-label">Full Name <span class="text-danger">*</span></label>
                <input class="form-control" @bind="_fullName" />
            </div>
            <div class="mb-3">
                <label class="form-label">Email <span class="text-danger">*</span></label>
                <input type="email" class="form-control" @bind="_email" />
            </div>
            <div class="mb-3">
                <label class="form-label">Phone <span class="text-danger">*</span></label>
                <input type="tel" class="form-control" @bind="_phone" />
            </div>
            <div class="mb-3">
                <label class="form-label">Address <span class="text-danger">*</span></label>
                <textarea class="form-control" rows="2" @bind="_address"></textarea>
            </div>
            <div class="d-flex justify-content-end">
                <button class="btn btn-primary" @onclick="NextStep" disabled="@_isProcessing">
                    @if (_isProcessing) { <span class="spinner-border spinner-border-sm me-1"></span> }
                    Next
                </button>
            </div>
        }

        @* ───── Step 2: Work History ───── *@
        @if (_currentStep == 2)
        {
            <h4>Work History</h4>
            @for (int i = 0; i < _workEntries.Count; i++)
            {
                var index = i;
                var entry = _workEntries[index];
                <div class="card mb-3">
                    <div class="card-body">
                        <div class="d-flex justify-content-between align-items-center mb-2">
                            <h6 class="mb-0">Position @(index + 1)</h6>
                            @if (_workEntries.Count > 1)
                            {
                                <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveWorkEntry(index)">Remove</button>
                            }
                        </div>
                        <div class="row mb-2">
                            <div class="col-md-6">
                                <label class="form-label">Company <span class="text-danger">*</span></label>
                                <input class="form-control" value="@entry.Company"
                                       @onchange="e => UpdateWork(index, entry with { Company = (string?)e.Value ?? string.Empty })" />
                            </div>
                            <div class="col-md-6">
                                <label class="form-label">Job Title <span class="text-danger">*</span></label>
                                <input class="form-control" value="@entry.Title"
                                       @onchange="e => UpdateWork(index, entry with { Title = (string?)e.Value ?? string.Empty })" />
                            </div>
                        </div>
                        <div class="row mb-2">
                            <div class="col-md-4">
                                <label class="form-label">Start Date <span class="text-danger">*</span></label>
                                <input type="date" class="form-control" value="@entry.StartDate?.ToString("yyyy-MM-dd")"
                                       @onchange="e => UpdateWork(index, entry with { StartDate = DateTime.TryParse((string?)e.Value, out var d) ? d : null })" />
                            </div>
                            <div class="col-md-4">
                                <label class="form-label">End Date</label>
                                <input type="date" class="form-control" value="@entry.EndDate?.ToString("yyyy-MM-dd")"
                                       disabled="@entry.IsCurrent"
                                       @onchange="e => UpdateWork(index, entry with { EndDate = DateTime.TryParse((string?)e.Value, out var d) ? d : null })" />
                            </div>
                            <div class="col-md-4 d-flex align-items-end mb-1">
                                <div class="form-check">
                                    <input class="form-check-input" type="checkbox" checked="@entry.IsCurrent"
                                           @onchange="e => UpdateWork(index, entry with { IsCurrent = (bool)(e.Value ?? false), EndDate = (bool)(e.Value ?? false) ? null : entry.EndDate })" />
                                    <label class="form-check-label">Currently working here</label>
                                </div>
                            </div>
                        </div>
                        <div class="mb-0">
                            <label class="form-label">Description</label>
                            <textarea class="form-control" rows="2" value="@entry.Description"
                                      @onchange="e => UpdateWork(index, entry with { Description = (string?)e.Value ?? string.Empty })"></textarea>
                        </div>
                    </div>
                </div>
            }
            <button class="btn btn-outline-secondary mb-3" @onclick="AddWorkEntry">+ Add Another Position</button>
            <div class="d-flex justify-content-between">
                <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
                <button class="btn btn-primary" @onclick="NextStep">Next</button>
            </div>
        }

        @* ───── Step 3: References ───── *@
        @if (_currentStep == 3)
        {
            <h4>References</h4>
            @for (int i = 0; i < _references.Count; i++)
            {
                var index = i;
                var refEntry = _references[index];
                <div class="card mb-3">
                    <div class="card-body">
                        <div class="d-flex justify-content-between align-items-center mb-2">
                            <h6 class="mb-0">Reference @(index + 1)</h6>
                            @if (_references.Count > 2)
                            {
                                <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveReference(index)">Remove</button>
                            }
                        </div>
                        <div class="row mb-2">
                            <div class="col-md-6">
                                <label class="form-label">Name <span class="text-danger">*</span></label>
                                <input class="form-control" value="@refEntry.Name"
                                       @onchange="e => UpdateRef(index, refEntry with { Name = (string?)e.Value ?? string.Empty })" />
                            </div>
                            <div class="col-md-6">
                                <label class="form-label">Relationship <span class="text-danger">*</span></label>
                                <input class="form-control" value="@refEntry.Relationship"
                                       @onchange="e => UpdateRef(index, refEntry with { Relationship = (string?)e.Value ?? string.Empty })" />
                            </div>
                        </div>
                        <div class="row">
                            <div class="col-md-6">
                                <label class="form-label">Email <span class="text-danger">*</span></label>
                                <input type="email" class="form-control" value="@refEntry.Email"
                                       @onchange="e => UpdateRef(index, refEntry with { Email = (string?)e.Value ?? string.Empty })" />
                            </div>
                            <div class="col-md-6">
                                <label class="form-label">Phone <span class="text-danger">*</span></label>
                                <input type="tel" class="form-control" value="@refEntry.Phone"
                                       @onchange="e => UpdateRef(index, refEntry with { Phone = (string?)e.Value ?? string.Empty })" />
                            </div>
                        </div>
                    </div>
                </div>
            }
            @if (_references.Count < 3)
            {
                <button class="btn btn-outline-secondary mb-3" @onclick="AddReference">+ Add Reference</button>
            }
            <div class="d-flex justify-content-between">
                <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
                <button class="btn btn-primary" @onclick="NextStep">Next</button>
            </div>
        }

        @* ───── Step 4: Cover Letter ───── *@
        @if (_currentStep == 4)
        {
            <h4>Cover Letter</h4>
            <div class="mb-2">
                <textarea class="form-control" rows="10" maxlength="2000"
                          @bind="_coverLetter" @bind:event="oninput"></textarea>
            </div>
            <div class="text-muted mb-3">@_coverLetter.Length / 2000 characters</div>
            <div class="d-flex justify-content-between">
                <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
                <button class="btn btn-primary" @onclick="NextStep">Next</button>
            </div>
        }

        @* ───── Step 5: Review & Submit ───── *@
        @if (_currentStep == 5)
        {
            <h4>Review Your Application</h4>

            @* Personal Info *@
            <div class="card mb-3">
                <div class="card-header d-flex justify-content-between align-items-center">
                    <strong>Personal Information</strong>
                    <button class="btn btn-link btn-sm p-0" @onclick='() => GoToStep(1)'>Edit</button>
                </div>
                <div class="card-body">
                    <dl class="row mb-0">
                        <dt class="col-sm-3">Name</dt><dd class="col-sm-9">@_fullName</dd>
                        <dt class="col-sm-3">Email</dt><dd class="col-sm-9">@_email</dd>
                        <dt class="col-sm-3">Phone</dt><dd class="col-sm-9">@_phone</dd>
                        <dt class="col-sm-3">Address</dt><dd class="col-sm-9">@_address</dd>
                    </dl>
                </div>
            </div>

            @* Work History *@
            <div class="card mb-3">
                <div class="card-header d-flex justify-content-between align-items-center">
                    <strong>Work History</strong>
                    <button class="btn btn-link btn-sm p-0" @onclick='() => GoToStep(2)'>Edit</button>
                </div>
                <div class="card-body">
                    @foreach (var entry in _workEntries)
                    {
                        <div class="mb-3">
                            <strong>@entry.Title</strong> at <strong>@entry.Company</strong><br />
                            <span class="text-muted">
                                @entry.StartDate?.ToString("MMM yyyy") &ndash;
                                @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))
                            </span>
                            @if (!string.IsNullOrWhiteSpace(entry.Description))
                            {
                                <p class="mt-1 mb-0">@entry.Description</p>
                            }
                        </div>
                    }
                </div>
            </div>

            @* References *@
            <div class="card mb-3">
                <div class="card-header d-flex justify-content-between align-items-center">
                    <strong>References</strong>
                    <button class="btn btn-link btn-sm p-0" @onclick='() => GoToStep(3)'>Edit</button>
                </div>
                <div class="card-body">
                    @foreach (var r in _references)
                    {
                        <div class="mb-2">
                            <strong>@r.Name</strong> (@r.Relationship)<br />
                            <span class="text-muted">@r.Email &bull; @r.Phone</span>
                        </div>
                    }
                </div>
            </div>

            @* Cover Letter *@
            <div class="card mb-3">
                <div class="card-header d-flex justify-content-between align-items-center">
                    <strong>Cover Letter</strong>
                    <button class="btn btn-link btn-sm p-0" @onclick='() => GoToStep(4)'>Edit</button>
                </div>
                <div class="card-body">
                    <p style="white-space: pre-wrap;" class="mb-0">@_coverLetter</p>
                </div>
            </div>

            <div class="d-flex justify-content-between">
                <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
                <button class="btn btn-success btn-lg" @onclick="SubmitApplication" disabled="@_isProcessing">
                    @if (_isProcessing) { <span class="spinner-border spinner-border-sm me-1"></span> }
                    Submit Application
                </button>
            </div>
        }
    }
</div>

@code {
    private static readonly string[] _stepLabels = ["Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"];

    private int _currentStep = 1;
    private bool _submitted;
    private bool _isProcessing;
    private int _applicationId;
    private List<string> _errors = [];

    // Step 1
    private string _fullName = string.Empty;
    private string _email = string.Empty;
    private string _phone = string.Empty;
    private string _address = string.Empty;

    // Step 2
    private List<WorkEntryModel> _workEntries = [new()];

    // Step 3
    private List<ReferenceModel> _references = [new(), new()];

    // Step 4
    private string _coverLetter = string.Empty;

    // Mutable models for form binding
    private record WorkEntryModel
    {
        public string Company { get; init; } = string.Empty;
        public string Title { get; init; } = string.Empty;
        public DateTime? StartDate { get; init; }
        public DateTime? EndDate { get; init; }
        public bool IsCurrent { get; init; }
        public string Description { get; init; } = string.Empty;
    }

    private record ReferenceModel
    {
        public string Name { get; init; } = string.Empty;
        public string Relationship { get; init; } = string.Empty;
        public string Email { get; init; } = string.Empty;
        public string Phone { get; init; } = string.Empty;
    }

    private void GoToStep(int step)
    {
        if (step < _currentStep && !_submitted)
        {
            _errors.Clear();
            _currentStep = step;
        }
    }

    private void PreviousStep()
    {
        _errors.Clear();
        if (_currentStep > 1) _currentStep--;
    }

    private async Task NextStep()
    {
        _errors.Clear();

        if (!ValidateCurrentStep())
            return;

        if (_currentStep == 1)
        {
            _isProcessing = true;
            var emailValid = await ApplicationService.ValidateEmailAsync(_email);
            _isProcessing = false;

            if (!emailValid)
            {
                _errors.Add("Please enter a valid email address.");
                return;
            }
        }

        if (_currentStep < 5) _currentStep++;
    }

    private bool ValidateCurrentStep()
    {
        switch (_currentStep)
        {
            case 1:
                if (string.IsNullOrWhiteSpace(_fullName)) _errors.Add("Full name is required.");
                if (string.IsNullOrWhiteSpace(_email)) _errors.Add("Email is required.");
                if (string.IsNullOrWhiteSpace(_phone)) _errors.Add("Phone is required.");
                if (string.IsNullOrWhiteSpace(_address)) _errors.Add("Address is required.");
                break;
            case 2:
                for (int i = 0; i < _workEntries.Count; i++)
                {
                    var e = _workEntries[i];
                    if (string.IsNullOrWhiteSpace(e.Company)) _errors.Add($"Position {i + 1}: Company is required.");
                    if (string.IsNullOrWhiteSpace(e.Title)) _errors.Add($"Position {i + 1}: Job title is required.");
                    if (e.StartDate is null) _errors.Add($"Position {i + 1}: Start date is required.");
                }
                break;
            case 3:
                for (int i = 0; i < _references.Count; i++)
                {
                    var r = _references[i];
                    if (string.IsNullOrWhiteSpace(r.Name)) _errors.Add($"Reference {i + 1}: Name is required.");
                    if (string.IsNullOrWhiteSpace(r.Relationship)) _errors.Add($"Reference {i + 1}: Relationship is required.");
                    if (string.IsNullOrWhiteSpace(r.Email)) _errors.Add($"Reference {i + 1}: Email is required.");
                    if (string.IsNullOrWhiteSpace(r.Phone)) _errors.Add($"Reference {i + 1}: Phone is required.");
                }
                break;
        }
        return _errors.Count == 0;
    }

    private void UpdateWork(int index, WorkEntryModel entry) => _workEntries[index] = entry;
    private void AddWorkEntry() => _workEntries.Add(new());
    private void RemoveWorkEntry(int index) => _workEntries.RemoveAt(index);

    private void UpdateRef(int index, ReferenceModel entry) => _references[index] = entry;
    private void AddReference() { if (_references.Count < 3) _references.Add(new()); }
    private void RemoveReference(int index) => _references.RemoveAt(index);

    private async Task SubmitApplication()
    {
        _isProcessing = true;

        var application = new JobApplication(
            new PersonalInfo(_fullName, _email, _phone, _address),
            new WorkHistory(_workEntries.Select(e =>
                new WorkEntry(e.Company, e.Title, e.StartDate ?? DateTime.MinValue, e.IsCurrent ? null : e.EndDate, e.Description)).ToList()),
            _references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
            _coverLetter
        );

        _applicationId = await ApplicationService.SubmitApplicationAsync(application);
        _isProcessing = false;
        _submitted = true;
    }
}
